// Reference copy of the original quadratic implementation (see reference-report.js).
const reference = require('./reference-report');

function rng(seed) {
  let s = seed;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32);
}

function randomOrders(n, customers, seed) {
  const r = rng(seed);
  const statuses = ['paid', 'paid', 'pending', 'refunded'];
  const orders = [];
  for (let i = 0; i < n; i++) {
    const day = 1 + Math.floor(r() * 3);
    const o = order(
      `o${Math.floor(r() * n * 0.9)}`, // collisions => duplicate deliveries
      `cus_${Math.floor(r() * customers)}`,
      statuses[Math.floor(r() * statuses.length)],
      Math.floor(r() * 20) * 50, // coarse amounts => spend ties
      `2026-10-0${day}T${String(Math.floor(r() * 3)).padStart(2, '0')}:00:00Z`,
      r() < 0.4 ? 'EUR' : 'USD',
    );
    orders.push(o);
  }
  return orders;
}

test('matches the original implementation exactly (ties, dupes, refunds, EUR)', () => {
  for (let seed = 1; seed <= 30; seed++) {
    const orders = randomOrders(400, 5 + seed, seed);
    for (const limit of [1, 10, 1000]) {
      assert.deepStrictEqual(summarize(orders, limit), reference.summarize(orders, limit));
    }
  }
});

test('handles 200,000 orders quickly', () => {
  const orders = randomOrders(200000, 20000, 99);
  const t0 = Date.now();
  const report = summarize(orders);
  assert.ok(Date.now() - t0 < 1000, 'summarize took too long');
  assert.strictEqual(report.length, 10);
});
EOF
